import { supabase, isSupabaseConfigured } from "./client";
import { rowToReserva, reservaToRow, type ReservaDbRow } from "./types";
import type { Reserva } from "@/store/useReservasStore";

const TABELA_RESERVAS = "reservas";

/**
 * Busca todas as reservas cadastradas no Supabase.
 */
export async function fetchReservasSupabase(): Promise<Reserva[] | null> {
  if (!isSupabaseConfigured()) {
    return null;
  }

  try {
    const { data, error } = await supabase
      .from(TABELA_RESERVAS)
      .select("*")
      .order("criada_em", { ascending: false });

    if (error) {
      console.error("[Supabase] Erro ao carregar reservas:", error.message);
      return null;
    }

    return (data as ReservaDbRow[]).map(rowToReserva);
  } catch (err) {
    console.error("[Supabase] Falha inesperada ao buscar reservas:", err);
    return null;
  }
}

/**
 * Busca reservas de um determinado mês e ano no Supabase (Lazy Loading).
 * @param ano Ano com 4 dígitos (ex.: 2026)
 * @param mes Mês de 1 a 12 (ex.: 10 para Outubro)
 * @returns Lista de reservas do mês ou null em caso de erro/não configurado.
 */
export async function fetchReservasPorMesSupabase(
  ano: number,
  mes: number
): Promise<Reserva[] | null> {
  if (!isSupabaseConfigured()) {
    return null;
  }

  try {
    const ultimoDia = new Date(ano, mes, 0).getDate();
    const dataInicio = `${ano}-${String(mes).padStart(2, "0")}-01`;
    const dataFim = `${ano}-${String(mes).padStart(2, "0")}-${String(ultimoDia).padStart(2, "0")}`;

    const { data, error } = await supabase
      .from(TABELA_RESERVAS)
      .select("*")
      .gte("data", dataInicio)
      .lte("data", dataFim)
      .order("data", { ascending: true });

    if (error) {
      console.error(
        `[Supabase] Erro ao carregar reservas do mês ${mes}/${ano}:`,
        error.message
      );
      return null;
    }

    return (data as ReservaDbRow[]).map(rowToReserva);
  } catch (err) {
    console.error(
      `[Supabase] Falha inesperada ao buscar reservas do mês ${mes}/${ano}:`,
      err
    );
    return null;
  }
}

/**
 * Remove colunas ausentes no schema cache do Supabase com base na mensagem de erro do PostgREST.
 * Retorna true se alguma coluna foi removida do payload, permitindo retry imediato sem quebrar o fluxo.
 */
function expurgarColunaIncompativel(
  payload: Record<string, unknown>,
  errorMessage: string
): boolean {
  const match = errorMessage.match(/Could not find the '(\w+)' column/i);
  if (match && match[1] && match[1] in payload) {
    console.warn(
      `[Supabase] Coluna '${match[1]}' ausente no schema cache de 'reservas'. Removendo do payload para compatibilidade retroativa.`
    );
    delete payload[match[1]];
    return true;
  }

  if (errorMessage.includes("user_id") && "user_id" in payload) {
    delete payload.user_id;
    return true;
  }

  return false;
}

/**
 * Insere uma nova reserva no banco de dados Supabase.
 * Trata graciosamente eventuais colunas ausentes no schema cache com retry automático resiliente.
 */
export async function inserirReservaSupabase(reserva: Reserva): Promise<boolean> {
  if (!isSupabaseConfigured()) {
    return false;
  }

  try {
    const payload: Record<string, unknown> = { ...reservaToRow(reserva) };
    let tentativa = 0;

    while (tentativa < 6) {
      const { error } = await supabase.from(TABELA_RESERVAS).insert([payload]);

      if (!error) {
        return true;
      }

      if (expurgarColunaIncompativel(payload, error.message)) {
        tentativa++;
        continue;
      }

      console.error("[Supabase] Erro ao inserir reserva:", error.message);
      return false;
    }

    return false;
  } catch (err) {
    console.error("[Supabase] Falha inesperada ao inserir reserva:", err);
    return false;
  }
}

/**
 * Insere várias reservas de uma só vez (ocorrências de um contrato recorrente).
 * Usa upsert por id para ser idempotente caso a geração seja repetida.
 */
export async function inserirReservasEmLoteSupabase(reservas: Reserva[]): Promise<boolean> {
  if (!isSupabaseConfigured() || reservas.length === 0) {
    return false;
  }

  try {
    const rows = reservas.map((r) => reservaToRow(r));
    const { error } = await supabase
      .from(TABELA_RESERVAS)
      .upsert(rows, { onConflict: "id" });

    if (error) {
      console.error("[Supabase] Erro ao inserir reservas em lote:", error.message);
      return false;
    }
    return true;
  } catch (err) {
    console.error("[Supabase] Falha inesperada ao inserir reservas em lote:", err);
    return false;
  }
}

/** Aplica o mesmo update a várias reservas (ex.: encerrar contrato → cancelar futuras). */
export async function atualizarReservasEmLoteSupabase(
  ids: string[],
  dados: Partial<Reserva>
): Promise<boolean> {
  if (!isSupabaseConfigured() || ids.length === 0) {
    return false;
  }

  try {
    const payload: Record<string, unknown> = { ...reservaToRow(dados) };
    let tentativa = 0;

    while (tentativa < 6) {
      const { error } = await supabase
        .from(TABELA_RESERVAS)
        .update(payload)
        .in("id", ids);

      if (!error) {
        return true;
      }

      if (expurgarColunaIncompativel(payload, error.message)) {
        tentativa++;
        continue;
      }

      console.error("[Supabase] Erro ao atualizar reservas em lote:", error.message);
      return false;
    }

    return false;
  } catch (err) {
    console.error("[Supabase] Falha inesperada ao atualizar reservas em lote:", err);
    return false;
  }
}

/**
 * Atualiza campos de uma reserva existente no Supabase.
 * Trata graciosamente caso colunas novas (ex: fidelidade) ainda não existam no schema do PostgreSQL,
 * removendo campos incompatíveis e tentando novamente sem interromper o fluxo da aplicação.
 */
export async function atualizarReservaSupabase(
  id: string,
  dados: Partial<Reserva>
): Promise<boolean> {
  if (!isSupabaseConfigured()) {
    return false;
  }

  try {
    const payload: Record<string, unknown> = { ...reservaToRow(dados) };
    let tentativa = 0;

    while (tentativa < 6) {
      const { error } = await supabase
        .from(TABELA_RESERVAS)
        .update(payload)
        .eq("id", id);

      if (!error) {
        return true;
      }

      if (expurgarColunaIncompativel(payload, error.message)) {
        tentativa++;
        continue;
      }

      console.error(`[Supabase] Erro ao atualizar reserva ${id}:`, error.message);
      return false;
    }

    return false;
  } catch (err) {
    console.error(`[Supabase] Falha inesperada ao atualizar reserva ${id}:`, err);
    return false;
  }
}

/**
 * Remove uma reserva do banco de dados Supabase.
 */
export async function removerReservaSupabase(id: string): Promise<boolean> {
  if (!isSupabaseConfigured()) {
    return false;
  }

  try {
    const { error } = await supabase
      .from(TABELA_RESERVAS)
      .delete()
      .eq("id", id);

    if (error) {
      console.error(`[Supabase] Erro ao remover reserva ${id}:`, error.message);
      return false;
    }

    return true;
  } catch (err) {
    console.error(`[Supabase] Falha inesperada ao remover reserva ${id}:`, err);
    return false;
  }
}

/**
 * Cria uma inscrição Realtime para escutar inserções, atualizações e deleções
 * na tabela 'reservas' em tempo real.
 */
export function subscreverReservasSupabase(
  onInsert: (reserva: Reserva) => void,
  onUpdate: (reserva: Reserva) => void,
  onDelete: (id: string) => void
) {
  if (!isSupabaseConfigured()) {
    return () => {};
  }

  // Remove qualquer canal anterior com mesmo prefixo para evitar conflito de callbacks após subscribe
  try {
    const canaisExistentes = supabase.getChannels();
    for (const c of canaisExistentes) {
      if (c.topic.includes("mudancas-reservas-realtime")) {
        void supabase.removeChannel(c);
      }
    }
  } catch (err) {
    console.warn("[Supabase] Aviso ao limpar canais anteriores:", err);
  }

  const canalId = `mudancas-reservas-realtime-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`;
  const canal = supabase
    .channel(canalId)
    .on(
      "postgres_changes",
      {
        event: "INSERT",
        schema: "public",
        table: TABELA_RESERVAS,
      },
      (payload) => {
        const nova = rowToReserva(payload.new as ReservaDbRow);
        onInsert(nova);
      }
    )
    .on(
      "postgres_changes",
      {
        event: "UPDATE",
        schema: "public",
        table: TABELA_RESERVAS,
      },
      (payload) => {
        const atualizada = rowToReserva(payload.new as ReservaDbRow);
        onUpdate(atualizada);
      }
    )
    .on(
      "postgres_changes",
      {
        event: "DELETE",
        schema: "public",
        table: TABELA_RESERVAS,
      },
      (payload) => {
        const idDeletado = (payload.old as { id?: string })?.id;
        if (idDeletado) {
          onDelete(idDeletado);
        }
      }
    )
    .subscribe();

  return () => {
    void supabase.removeChannel(canal);
  };
}
/**
 * Dados do complexo esportivo — um único estabelecimento com múltiplas quadras idênticas.
 * Todas as quadras têm o mesmo piso (PU) e as mesmas comodidades.
 */

// ─── Esportes disponíveis ─────────────────────────────────────────────────────

/**
 * Esporte que será praticado na reserva (campo opcional).
 * Quando informado, a administração prepara a quadra adequadamente
 * (ex.: instalar rede de vôlei, posicionar traves de futsal, etc.).
 */
export type Esporte =
  | "Futsal"
  | "Vôlei"
  | "Basquete"
  | "Handebol"
  | "Outro";

export const ESPORTES: Esporte[] = [
  "Futsal",
  "Vôlei",
  "Basquete",
  "Handebol",
  "Outro",
];

/** Equipamentos que a administração monta por esporte */
export const PREPARACAO_POR_ESPORTE: Record<Esporte, string> = {
  Futsal: "Posicionamento e fixação das traves de futsal",
  Vôlei: "Montagem da rede e marcação das linhas de vôlei",
  Basquete: "Posicionamento das tabelas de basquete",
  Handebol: "Posicionamento das traves de handebol",
  Outro: "Preparação padrão (sem equipamento específico)",
};

// ─── Quadras ──────────────────────────────────────────────────────────────────

export interface Quadra {
  id: string;
  numero: number;        // "Quadra 1", "Quadra 2", etc.
  descricao: string;
}

/**
 * Comodidades comuns a todas as quadras do complexo.
 * Piso de pintura PU — todas idênticas.
 */
export const COMODIDADES_COMPLEXO: string[] = [
  "Piso PU (pintura poliuretânica)",
  "Vestiário masculino e feminino",
  "Iluminação LED noturna",
  "Estacionamento gratuito",
  "Bebedouro",
];

/** Quadras do complexo — altere a quantidade conforme o estabelecimento */
export const QUADRAS: Quadra[] = [
  { id: "q1", numero: 1, descricao: "Quadra poliesportiva coberta" },
  { id: "q2", numero: 2, descricao: "Quadra poliesportiva coberta" },
  { id: "q3", numero: 3, descricao: "Quadra poliesportiva coberta" },
];

/** Valor padrão por hora (igual para todas as quadras) */
export const VALOR_HORA = 90; // em reais

// ─── Horários ─────────────────────────────────────────────────────────────────

/** Horários disponíveis para agendamento (blocos de 1 hora) */
export const HORARIOS_DISPONIVEIS = [
  "08:00", "09:00", "10:00", "11:00", "12:00",
  "13:00", "14:00", "15:00", "16:00", "17:00",
  "18:00", "19:00", "20:00", "21:00",
];
/**
 * Constantes de negócio centralizadas — single source of truth.
 * Nenhuma regra de negócio deve ser hardcoded nos componentes.
 */

// ─── Financeiro ───────────────────────────────────────────────────────────────

/** Percentual cobrado como sinal no momento da reserva (40%) */
export const PERCENTUAL_SINAL = 0.4;

/** Horas mínimas de antecedência para cancelamento sem cobrança */
export const TOLERANCIA_CANCELAMENTO_HORAS = 24;

/** Tabela de preços por faixa de horário (R$/hora) */
export const PRECOS = {
  MANHA: 70, // 08:00 – 11:59
  TARDE: 90, // 12:00 – 16:59
  NOITE: 110, // 17:00 – 21:59
} as const;

// ─── Agendamento ──────────────────────────────────────────────────────────────

/** Quantidade de dias no futuro disponíveis para agendamento (hoje + 7) */
export const DIAS_AGENDAMENTO_FUTURO = 7;

// ─── Complexo ─────────────────────────────────────────────────────────────────

export const NOME_COMPLEXO = "Complexo Esportivo Reservei";
export const ENDERECO_COMPLEXO = "Rua das Quadras, 100 – Centro";
export const TELEFONE_COMPLEXO = "(11) 99999-0000";

// ─── Funções Utilitárias ──────────────────────────────────────────────────────

/**
 * Retorna o valor (R$) cobrado por hora de acordo com o horário de início.
 * Regra: manhã (08-11h) R$70 | tarde (12-16h) R$90 | noite (17-22h) R$110
 */
export function calcularValorHora(horaInicio: string): number {
  const hora = parseInt(horaInicio.split(":")[0], 10);
  if (hora >= 8 && hora < 12) return PRECOS.MANHA;
  if (hora >= 12 && hora < 18) return PRECOS.TARDE;
  return PRECOS.NOITE;
}

/** Soma os valores de cada slot horário selecionado */
export function calcularValorTotal(horarios: string[]): number {
  return horarios.reduce((total, h) => total + calcularValorHora(h), 0);
}

/** Valor do sinal (40% do total, arredondado para centavos) */
export function calcularValorSinal(valorTotal: number): number {
  return Math.round(valorTotal * PERCENTUAL_SINAL * 100) / 100;
}

/** Valor pendente após pagamento do sinal */
export function calcularValorPendente(valorTotal: number): number {
  return Math.round(valorTotal * (1 - PERCENTUAL_SINAL) * 100) / 100;
}

/** Formata valor monetário em Real brasileiro com proteção contra NaN e valores inválidos */
export function formatarMoeda(valor: number): string {
  const num = typeof valor === "number" ? valor : Number(valor);
  if (isNaN(num) || !isFinite(num)) {
    return (0).toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
  }
  return num.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

/** Formata data ISO "YYYY-MM-DD" para exibição amigável */
export function formatarDataExibicao(
  dataISO: string,
  opts: Intl.DateTimeFormatOptions = {
    weekday: "short",
    day: "numeric",
    month: "short",
  }
): string {
  const [year, month, day] = dataISO.split("-").map(Number);
  return new Date(year, month - 1, day).toLocaleDateString("pt-BR", opts);
}

/** Verifica se os horários selecionados são estritamente consecutivos */
export function saoConsecutivos(horarios: string[]): boolean {
  if (horarios.length <= 1) return true;
  const sorted = [...horarios].sort();
  for (let i = 1; i < sorted.length; i++) {
    const prev = parseInt(sorted[i - 1].split(":")[0], 10);
    const curr = parseInt(sorted[i].split(":")[0], 10);
    if (curr - prev !== 1) return false;
  }
  return true;
}

/**
 * Formata um objeto Date para "YYYY-MM-DD" usando o fuso horário LOCAL.
 * ⚠️ Nunca use toISOString() para isso — ela retorna UTC e quebra em deploy.
 */
function formatarDataLocal(d: Date): string {
  const ano = d.getFullYear();
  const mes = String(d.getMonth() + 1).padStart(2, "0");
  const dia = String(d.getDate()).padStart(2, "0");
  return `${ano}-${mes}-${dia}`;
}

/** Gera os próximos N dias (hoje inclusive) no formato "YYYY-MM-DD" */
export function gerarDiasDisponiveis(
  total: number = DIAS_AGENDAMENTO_FUTURO + 1
): string[] {
  const result: string[] = [];
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  for (let i = 0; i < total; i++) {
    const d = new Date(today);
    d.setDate(today.getDate() + i);
    result.push(formatarDataLocal(d)); // ✅ fuso horário local
  }
  return result;
}

/** Retorna a data de hoje no formato "YYYY-MM-DD" (fuso horário local) */
export function getHoje(): string {
  return formatarDataLocal(new Date()); // ✅ fuso horário local, não UTC
}

/** Mascara WhatsApp: (00) 00000-0000 */
export function mascaraWhatsApp(valor: string): string {
  if (!valor) return "";
  const nums = valor.replace(/\D/g, "").slice(0, 11);
  if (!nums) return "";
  if (nums.length <= 2) return `(${nums}`;
  if (nums.length <= 7) return `(${nums.slice(0, 2)}) ${nums.slice(2)}`;
  return `(${nums.slice(0, 2)}) ${nums.slice(2, 7)}-${nums.slice(7)}`;
}

/** Mascara CPF: 000.000.000-00 */
export function mascaraCPF(valor: string): string {
  const nums = valor.replace(/\D/g, "").slice(0, 11);
  if (nums.length <= 3) return nums;
  if (nums.length <= 6) return `${nums.slice(0, 3)}.${nums.slice(3)}`;
  if (nums.length <= 9)
    return `${nums.slice(0, 3)}.${nums.slice(3, 6)}.${nums.slice(6)}`;
  return `${nums.slice(0, 3)}.${nums.slice(3, 6)}.${nums.slice(6, 9)}-${nums.slice(9)}`;
}

/** 
 * Verifica se um horário de uma data específica expirou.
 * Regras:
 * - Se a data selecionada for posterior a hoje: nunca expira (dias futuros sempre disponíveis).
 * - Se a data selecionada for anterior a hoje: sempre expirada.
 * - Se for hoje: expira se faltar menos de `minutosAntecedencia` para o início do horário.
 *
 * @param dataSelecionada Formato "YYYY-MM-DD"
 * @param horario Formato "HH:mm"
 * @param minutosAntecedencia Limite de minutos antes do horário para considerar expirado
 */
export function isHorarioExpirado(
  dataSelecionada: string,
  horario: string,
  minutosAntecedencia: number
): boolean {
  if (!dataSelecionada || !horario) return false;

  const hoje = getHoje();
  if (dataSelecionada > hoje) {
    return false; // Dias futuros nunca têm horários expirados
  }
  if (dataSelecionada < hoje) {
    return true; // Dias passados estão expirados
  }

  // É o dia de hoje: calcula horário local
  const agora = new Date();
  const [ano, mes, dia] = dataSelecionada.split("-").map(Number);
  const [hora, minuto] = horario.split(":").map(Number);

  const dataHorario = new Date(ano, mes - 1, dia, hora, minuto, 0, 0);
  const tempoLimite = new Date(dataHorario.getTime() - minutosAntecedencia * 60000);

  return agora.getTime() > tempoLimite.getTime();
}


/**
 * Normaliza número de telefone brasileiro para o formato internacional E.164 (+55...).
 * Exemplo: "(11) 99999-8888" -> "+5511999998888"
 */
export function normalizarTelefoneE164(telefone: string): string {
  const nums = telefone.replace(/\D/g, "");
  if (!nums) return "";
  if (nums.startsWith("55") && nums.length >= 12) {
    return `+${nums}`;
  }
  return `+55${nums}`;
}

export interface RegrasSenha {
  minimo: boolean;
  maiuscula: boolean;
  especial: boolean;
}

/**
 * Valida os requisitos de segurança da senha:
 * - Mínimo de 6 caracteres
 * - Pelo menos uma letra maiúscula
 * - Pelo menos um caractere especial (!@#$%^&*...)
 */
export function validarSenhaForte(senha: string): {
  valido: boolean;
  erros: string[];
  regras: RegrasSenha;
} {
  const regras: RegrasSenha = {
    minimo: senha.length >= 6,
    maiuscula: /[A-Z]/.test(senha),
    especial: /[^A-Za-z0-9]/.test(senha),
  };

  const erros: string[] = [];
  if (!regras.minimo) erros.push("A senha deve ter pelo menos 6 caracteres.");
  if (!regras.maiuscula) erros.push("A senha deve conter ao menos uma letra maiúscula (A-Z).");
  if (!regras.especial) erros.push("A senha deve conter ao menos um caractere especial (!@#$...).");

  return {
    valido: erros.length === 0,
    erros,
    regras,
  };
}

